import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';
import Web3 from 'web3';
import WalletConnectProvider from '@walletconnect/web3-provider';

interface WalletContextType {
  account: string | null;
  connectWallet: () => Promise<void>;
  disconnectWallet: () => Promise<void>;
  web3: Web3 | null;
  isConnected: boolean;
  balance: string | null;
  chainId: number | null;
}

const WalletContext = createContext<WalletContextType | undefined>(undefined);

export const useWallet = () => {
  const context = useContext(WalletContext);
  if (!context) {
    throw new Error('useWallet must be used within a WalletProvider');
  }
  return context;
};

export const WalletProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [account, setAccount] = useState<string | null>(null);
  const [web3, setWeb3] = useState<Web3 | null>(null);
  const [balance, setBalance] = useState<string | null>(null);
  const [chainId, setChainId] = useState<number | null>(null);

  const connectWallet = useCallback(async () => {
    try {
      const provider = new WalletConnectProvider({
        rpc: {
          1: "https://cloudflare-eth.com/",
          137: "https://polygon-rpc.com/",
          56: "https://bsc-dataseed.binance.org/",
        },
        chainId: 1,
      });

      // Enable session (triggers QR Code modal)
      await provider.enable();
      
      const web3Instance = new Web3(provider as any);
      setWeb3(web3Instance);

      const accounts = await web3Instance.eth.getAccounts();
      if (accounts.length > 0) {
        const userAccount = accounts[0];
        setAccount(userAccount);

        try {
          const balanceWei = await web3Instance.eth.getBalance(userAccount);
          const balanceEth = web3Instance.utils.fromWei(balanceWei, 'ether');
          setBalance(parseFloat(balanceEth).toFixed(4));
        } catch (balanceError) {
          console.warn("Failed to fetch balance:", balanceError);
          setBalance("0.0000");
        }

        try {
          const networkId = await web3Instance.eth.getChainId();
          setChainId(Number(networkId));
        } catch (networkError) {
          console.warn("Failed to fetch network ID:", networkError);
          setChainId(1); // Default to Ethereum mainnet
        }
      }

      // Set up event listeners
      provider.on("accountsChanged", (accounts: string[]) => {
        if (accounts.length > 0) {
          setAccount(accounts[0]);
          // Refetch balance for new account
          web3Instance.eth.getBalance(accounts[0])
            .then(balanceWei => {
              const balanceEth = web3Instance.utils.fromWei(balanceWei, 'ether');
              setBalance(parseFloat(balanceEth).toFixed(4));
            })
            .catch(() => setBalance("0.0000"));
        } else {
          setAccount(null);
          setBalance(null);
        }
      });

      provider.on("chainChanged", (chainId: number) => {
        setChainId(chainId);
      });

      provider.on("disconnect", () => {
        console.log("Wallet disconnected");
        setAccount(null);
        setWeb3(null);
        setBalance(null);
        setChainId(null);
      });

    } catch (error: any) {
      console.error("Failed to connect wallet:", error);
      
      // Handle specific WalletConnect errors
      if (error.message?.includes('User closed modal') || error.message?.includes('User rejected')) {
        throw new Error('Connection cancelled by user');
      } else if (error.message?.includes('No provider')) {
        throw new Error('No wallet found. Please install a wallet app.');
      } else if (error.message?.includes('Network Error')) {
        throw new Error('Network error. Please check your internet connection.');
      } else {
        throw new Error('Failed to connect wallet. Please try again.');
      }
    }
  }, []);

  const disconnectWallet = useCallback(async () => {
    try {
      if (web3 && (web3.currentProvider as any).disconnect) {
        await (web3.currentProvider as any).disconnect();
      }
    } catch (error) {
      console.warn("Error during wallet disconnect:", error);
      // Continue with cleanup even if disconnect fails
    } finally {
      // Always clean up state regardless of disconnect success
      setAccount(null);
      setWeb3(null);
      setBalance(null);
      setChainId(null);
    }
  }, [web3]);

  const value = {
    account,
    connectWallet,
    disconnectWallet,
    web3,
    isConnected: !!account,
    balance,
    chainId,
  };

  return <WalletContext.Provider value={value}>{children}</WalletContext.Provider>;
};
